const projects=[
 {name:'RemoteDesk',type:'SaaS · Website design',image:'assets/remotedesk.jpeg',description:'A website experience for RemoteDesk, a SaaS security platform. Clear product storytelling and a focused visual direction for a complex category.'},
 {name:'Quickads',type:'AI SaaS · Digital experience',image:'assets/quickads.png',description:'A digital experience for Quickads, an AI advertising platform. A confident presentation built around the product and what it makes possible.'},
 {name:'Tiger Loans',type:'Fintech · Design & development',image:'assets/tigerloans.jpg',description:'Website design and development for Tiger Loans. A clear and approachable digital presence for a financial services business.'},
 {name:'Neon Sundae',type:'Web3 · Product design',image:'assets/neonsundae.png',description:'Product design for a Web3 CRM tool. Bringing a distinctive identity and structure to the platform experience.'},
 {name:'Finergic',type:'Finance · MVP & dashboard',image:'assets/finergic.png',description:'MVP finance dashboard design for Finergic. Organizing financial information into a focused product interface.'},
 {name:'CarbonX',type:'Climate tech · Website design',image:'assets/carbonx.png',description:'Website design for a carbon credits trading business. A digital presence that makes the offering easier to explore.'}
];
let currentSlide=0;
function showSlide(index){currentSlide=index;const project=projects[index];document.querySelector('#showcase-image').src=project.image;document.querySelector('#showcase-image').alt=project.name+' design by Blitz Studio';document.querySelector('#showcase-title').textContent=project.name;document.querySelector('#showcase-type').textContent=project.type;document.querySelector('.showcase-count').textContent='0'+(index+1)+' / 04';document.querySelectorAll('[data-slide]').forEach((button,i)=>{button.classList.toggle('selected',i===index);button.setAttribute('aria-pressed',i===index)})}
document.querySelector('#showcase-next').addEventListener('click',()=>showSlide((currentSlide+1)%4));document.querySelectorAll('[data-slide]').forEach(button=>button.addEventListener('click',()=>showSlide(Number(button.dataset.slide))));
document.querySelectorAll('.principle').forEach(button=>button.addEventListener('click',()=>{const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',!open);button.querySelector('.flip-hint').textContent=open?'+':'−'}));
const steps=[
 {kicker:'LET’S GET ON THE SAME PAGE',card:'It starts with<br>a conversation.',items:['Your vision','Your audience','A clear plan'],note:'Great things start here. ✦',number:'01 / DISCOVERY',title:'First, we listen.',text:'We get to know your business, your audience, and what success looks like. Together, we define a focused brief, the scope, and a plan for getting there.'},
 {kicker:'FROM DIRECTION TO DESIGN',card:'Ideas take shape.<br>Details come alive.',items:['A visual direction','Thoughtful interfaces','A working experience'],note:'A little craft. A lot of care. ✦',number:'02 / DESIGN & BUILD',title:'Then, we make it real.',text:'We turn the brief into designs, explore the details, and build the experience. You see the work taking shape and stay close to the decisions that matter.'},
 {kicker:'BETTER, TOGETHER',card:'Your perspective.<br>Our next iteration.',items:['Open conversations','Focused feedback','Thoughtful refinements'],note:'The details make the difference. ✦',number:'03 / REFINEMENT',title:'Good gets even better.',text:'We share progress, gather your feedback, and refine the work together. Clear communication keeps the project moving and the final result aligned with your vision.'},
 {kicker:'READY FOR THE REAL WORLD',card:'Made with care.<br>Ready to launch.',items:['Final quality checks','Launch day','A clear handover'],note:'Here’s to what comes next. ✦',number:'04 / LAUNCH',title:'Out into the world.',text:'We check the details, support your launch, and hand over what your team needs. Your new website or product is ready for its next chapter.'}
];
const tabs=[...document.querySelectorAll('[data-step]')];function selectStep(index){const step=steps[index];tabs.forEach((tab,i)=>{tab.setAttribute('aria-selected',i===index);tab.tabIndex=i===index?0:-1});document.querySelector('#process-panel').setAttribute('aria-labelledby','step-'+index);document.querySelector('#process-kicker').textContent=step.kicker;document.querySelector('#process-card-title').innerHTML=step.card;document.querySelector('#process-items').replaceChildren(...step.items.map(text=>{const span=document.createElement('span');const check=document.createElement('i');check.textContent='✓';span.append(check,document.createTextNode(text));return span}));document.querySelector('#process-note').textContent=step.note;document.querySelector('#process-number').textContent=step.number;document.querySelector('#process-title').textContent=step.title;document.querySelector('#process-text').textContent=step.text;document.querySelector('.brief-bottom span:last-child').textContent='0'+(index+1)+' — 04'}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectStep(index));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%4;if(event.key==='ArrowLeft')next=(index+3)%4;if(event.key==='Home')next=0;if(event.key==='End')next=3;if(next!==undefined){event.preventDefault();selectStep(next);tabs[next].focus()}})});
const menuButton=document.querySelector('.menu-toggle'),menu=document.querySelector('#mobile-menu');function closeMenu(){menu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','Open menu')}menuButton.addEventListener('click',()=>{menu.hidden=!menu.hidden;menuButton.setAttribute('aria-expanded',!menu.hidden);menuButton.setAttribute('aria-label',menu.hidden?'Open menu':'Close menu')});menu.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!menu.hidden){closeMenu();menuButton.focus()}});document.addEventListener('click',event=>{if(!menu.hidden&&!menu.contains(event.target)&&!menuButton.contains(event.target))closeMenu()});
const sectionObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting)document.querySelectorAll('.nav-links a').forEach(link=>{const active=link.hash==='#'+entry.target.id;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})}},{rootMargin:'-15% 0px -65% 0px',threshold:0});document.querySelectorAll('main section[id]').forEach(section=>sectionObserver.observe(section));
const dialog=document.querySelector('#project-dialog');document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const project=projects[Number(button.dataset.project)];document.querySelector('#dialog-title').textContent=project.name;document.querySelector('#dialog-description').textContent=project.description;document.querySelector('#dialog-image').src=project.image;document.querySelector('#dialog-image').alt=project.name+' project by Blitz Studio';dialog.showModal();document.body.style.overflow='hidden'}));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>document.body.style.overflow='');
function setTime(){const now=new Date();document.querySelector('#local-time').textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(now);document.querySelector('#year').textContent=now.getFullYear()}setTime();setInterval(setTime,60000);
